SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0450000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 45, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "45", "printedPageNumber": 45, "pdfPageNumber": 428, "sequenceIndex": 35, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0450000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part I (b)—Warning on Discard of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "placed His gracious hand on my bosom. I felt its solacing coolness right through my heart, and the entire universe was revealed to me. I said, ''They are arguing about the things which exalt, the things which atone for the sins, the rewards for the paces taken while going for salaat (with Jamaat), the virtues of performing wudhu properly when it was very cold, and the blessings that a person deserves when after performing one salaat he keeps on sitting in musjid till the next salaat.'' A person particular of these shall live a blessed life and shall die an enviable death.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Prophet (Sallallaho alaihe wasallam) is reported (in many ahaadith) to have said, \"Allah says, ''O, Son of Aadam! Say four rakaats of salaat in the early part of the day. I shall help thee in accomplishing all thy jobs during the rest of the day.''\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said in a hadith: \"Salaat is the cause of Allah''s pleasure, is loved by the Angels, is a tradition of the Prophets, gives enlightenment about Allah, causes the prayers to be granted, blesses the daily bread, is the root of Imaan, refreshes the body, is a weapon against the enemy, shall intercede for its adherent, is a light in the darkness and a companion in the loneliness of the grave, is a reply to the questioning of Angels, is a shade against the Sun on the Day of Judgement, is a protection against the fire of Hell, is a weight for the scales of good deeds, is a means of swift crossing over the Siraat and is a key to Paradise.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Uthman (Radhiyallaho anho) is reported to have said, \"Allah bestows nine favours on a person who guards his salaat and is particular in performing it at its appointed hours: viz: He is loved by Allah, he enjoys good health, is constantly under the protection of angels, his home is blessed, the light of righteousness shines on his face, his heart is made soft, he shall cross the Siraat with the speed of lightning, he is saved from Hell, and his neighbours in Paradise are those about whom Allah has said,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أَلَا إِنَّ أَوْلِيَاءَ اللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "''There shall be no fear come upon them, neither shall they grieve (II: 36).''", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450700-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 7, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Prophet (Sallallaho alaihe wasallam) says, \"Salaat is the Pillar of Islam and it has ten virtues, viz: It is a charm of the face, a light of the heart, health and refreshment for the body, a company in the grave, a means for the descent", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}]}'::jsonb);